import{_ as t,o as a,c as o,an as s}from"./chunks/framework.DL3WMPYA.js";const i="/Kraken.jl/stable/assets/thermal-natural-convection-nu.C95FViak.png",r="/Kraken.jl/stable/assets/thermal-natural-convection-convergence.C7ZfIWs7.png",y=JSON.parse('{"title":"Thermal Natural Convection","description":"","frontmatter":{},"headers":[],"relativePath":"users/benchmarks/thermal-natural-convection.md","filePath":"users/benchmarks/thermal-natural-convection.md","lastUpdated":null}'),n={name:"users/benchmarks/thermal-natural-convection.md"};function l(d,e,c,h,g,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="Thermal-Natural-Convection" tabindex="-1">Thermal Natural Convection <a class="header-anchor" href="#Thermal-Natural-Convection" aria-label="Permalink to &quot;Thermal Natural Convection {#Thermal-Natural-Convection}&quot;">​</a></h1><p>Steady 2D natural convection in a differentially-heated square cavity at Ra = 10³, 10⁴, 10⁵ (Pr = 0.71). Kraken&#39;s double-distribution thermal LBM matches the canonical <strong>de Vahl Davis (1983)</strong> benchmark to <strong>Nu err &lt; 1 %</strong> at every Ra (velocity extrema &lt; 1 %), cross-checked against OpenFOAM <code>buoyantBoussinesqSimpleFoam</code>.</p><p>de Vahl Davis 1983 (black markers), Kraken LBM (blue squares), OpenFOAM (orange triangles); the OF Ra = 10⁴ point is omitted as under-converged.</p><p><img src="'+i+'" alt=""></p><p>The Ra = 10⁵ convergence ladder shows the monotone descent of the Nu error with mesh and the crossing of the 1 % gate at N ≈ 384.</p><p><img src="'+r+`" alt=""></p><h2 id="Result" tabindex="-1">Result <a class="header-anchor" href="#Result" aria-label="Permalink to &quot;Result {#Result}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Ra</th><th style="text-align:right;">Backend</th><th style="text-align:right;">Mesh</th><th style="text-align:right;">Nu (Kraken)</th><th style="text-align:right;">Nu (dVD)</th><th style="text-align:right;">Nu err</th></tr></thead><tbody><tr><td style="text-align:right;">10³</td><td style="text-align:right;">CPU F64</td><td style="text-align:right;">192²</td><td style="text-align:right;">1.126</td><td style="text-align:right;">1.117</td><td style="text-align:right;"><strong>+0.79 %</strong></td></tr><tr><td style="text-align:right;">10⁴</td><td style="text-align:right;">Metal F32</td><td style="text-align:right;">320²</td><td style="text-align:right;">2.259</td><td style="text-align:right;">2.238</td><td style="text-align:right;"><strong>+0.93 %</strong></td></tr><tr><td style="text-align:right;">10⁵</td><td style="text-align:right;">Metal F32</td><td style="text-align:right;">384²</td><td style="text-align:right;">4.544</td><td style="text-align:right;">4.509</td><td style="text-align:right;"><strong>+0.79 %</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Measured before the thermal walls moved (issue #97)</p><p>The rows above, the convergence plot and the 3D numbers below were measured when the thermal Dirichlet walls sat on the first and last nodes (cavity width <code>N − 1</code>) while the no-slip walls sat half a spacing outside them (width <code>N</code>). The thermal walls are now half-way too, so both cavities have width <code>N</code>. These rows have not been re-run since; see <a href="/Kraken.jl/stable/users/benchmarks/thermal-natural-convection#wall-position-re-measured-on-cpu">Wall position</a> for the numbers that have.</p></div><p>Both mid-plane velocity extrema (<code>u_max*</code>, <code>v_max*</code>, normalised by <code>α/L</code>) are under 1 % at every Ra. OpenFOAM independently corroborates de Vahl Davis at Ra = 10³ (−0.56 %) and Ra = 10⁵ (−0.60 %) — two CFD codes (FVM SIMPLE and LBM) bracketing the benchmark from opposite signs. Full data: <code>benchmarks/results/repro/thermal/kraken_natconv_results.csv</code>.</p><p><strong>Per-Ra precision recipe (a real finding).</strong> The thermal boundary layer thins as Ra^(1/4), so the resolution needed to clear the 1 % gate grows with Ra: at Ra = 10⁵ the Nu error descends monotonically and only crosses below 1 % at <strong>N ≈ 384</strong> (see the convergence plot). At the opposite end, <strong>Ra = 10³ must run in Float64</strong>: its buoyancy force <code>β g ∝ 1/N³ ≈ 10⁻⁹</code> LU sinks below the Float32 epsilon for <code>N ≥ 320</code> and the convection cell collapses toward conduction. Where both precisions are valid (Ra = 10⁴/10⁵ at N=128) <strong>Metal-F32 and CPU-F64 agree on Nu to 0.07–0.09 %</strong>.</p><h2 id="Wall-position-re-measured-on-CPU" tabindex="-1">Wall position (re-measured on CPU) <a class="header-anchor" href="#Wall-position-re-measured-on-CPU" aria-label="Permalink to &quot;Wall position (re-measured on CPU) {#Wall-position-re-measured-on-CPU}&quot;">​</a></h2><p>The hot and cold walls use the half-way anti-bounce-back rule: each wall sits half a lattice spacing outside the first (last) node, exactly where the no-slip bounce-back wall of the flow sits. The cavity width is <code>H = N</code> for the flow, the temperature and the Rayleigh number. <code>Nu</code> is the hot-wall average of the second-order one-sided gradient through the wall value and the first two nodes, <code>∂T/∂n = (−8 T_w + 9 T_1 − T_2) / (3 Δx)</code>, over rows <code>2 … N − 1</code>.</p><p>Measured 2026-11-03 with <code>run_natural_convection_2d</code>, CPU Float64, <code>ν = 0.05</code>, <code>Pr = 0.71</code>, run to a steady <code>Nu</code>: at <code>N = 64</code>, 30 000 steps at <code>Ra = 10³</code> and 60 000 at <code>Ra = 10⁴</code>; doubling the step count moves <code>Nu</code> by less than <code>10⁻⁵</code> in both cases. The pure-conduction row uses <code>N = 32</code> and 40 000 steps; the <code>N = 96</code> rows ran 70 000 and 135 000 steps without a step-doubling check.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Case</th><th style="text-align:right;">N</th><th style="text-align:right;">Nu, on-node walls (before)</th><th style="text-align:right;">Nu, half-way walls (now)</th><th style="text-align:right;">Reference</th></tr></thead><tbody><tr><td style="text-align:right;">Ra = 0</td><td style="text-align:right;">32</td><td style="text-align:right;">1.0351</td><td style="text-align:right;">1.0000049</td><td style="text-align:right;">1 (conduction)</td></tr><tr><td style="text-align:right;">Ra = 10³</td><td style="text-align:right;">64</td><td style="text-align:right;">1.1423 (+2.26 %)</td><td style="text-align:right;">1.1185 (+0.13 %)</td><td style="text-align:right;">dVD Nu₀ = 1.117</td></tr><tr><td style="text-align:right;">Ra = 10⁴</td><td style="text-align:right;">64</td><td style="text-align:right;">2.3585 (+5.39 %)</td><td style="text-align:right;">2.2535 (+0.69 %)</td><td style="text-align:right;">dVD Nu₀ = 2.238</td></tr><tr><td style="text-align:right;">Ra = 10³</td><td style="text-align:right;">96</td><td style="text-align:right;">not measured</td><td style="text-align:right;">1.1183 (+0.12 %)</td><td style="text-align:right;">dVD Nu₀ = 1.117</td></tr><tr><td style="text-align:right;">Ra = 10⁴</td><td style="text-align:right;">96</td><td style="text-align:right;">not measured</td><td style="text-align:right;">2.2509 (+0.58 %)</td><td style="text-align:right;">dVD Nu₀ = 2.238</td></tr></tbody></table><p>With the walls on the nodes, the thermal cavity was one spacing narrower than the flow cavity, an error of order <code>1/N</code> on <code>Nu</code>. Moving the walls removes it; at <code>N = 64</code> both Rayleigh numbers are now within 1 % of de Vahl Davis.</p><p>In pure conduction the residual departure from <code>Nu = 1</code> does not come from the Dirichlet walls: with the other axes periodic, the half-way walls give the linear profile and <code>Nu = 1</code> to round-off (test suite, 2D and 3D). In the closed cavity the adiabatic bounce-back walls bend the profile near the top and bottom walls. The mid-height deviation from the linear profile decreases as <code>1/N²</code> (<code>5.2 × 10⁻⁵</code> at <code>N = 16</code>, <code>1.3 × 10⁻⁵</code> at <code>N = 32</code>), and <code>Nu − 1 = 3.1 × 10⁻⁴</code> at <code>N = 16</code>, <code>4.9 × 10⁻⁶</code> at <code>N = 32</code> (<code>1.4 × 10⁻³</code> for the 3D box at <code>N = 12</code>).</p><h2 id="Methodology" tabindex="-1">Methodology <a class="header-anchor" href="#Methodology" aria-label="Permalink to &quot;Methodology {#Methodology}&quot;">​</a></h2><p><strong>Kraken (thermal LBM, double-distribution D2Q9).</strong> D2Q9 BGK flow + a second D2Q9 distribution advecting temperature, with Boussinesq buoyancy <code>F = β g (T − T₀)</code> (the code applies no density factor) coupled back into the flow. Hot left wall (<code>T = 1</code>), cold right wall (<code>T = 0</code>), adiabatic top/bottom, all walls no-slip (halfway bounce-back), hot and cold walls half-way anti-bounce-back (see <a href="/Kraken.jl/stable/users/benchmarks/thermal-natural-convection#wall-position-re-measured-on-cpu">Wall position</a>). Driver <code>run_natural_convection_2d</code>, iterated to a steady Nusselt residual.</p><p><strong>OpenFOAM cross-check (<code>buoyantBoussinesqSimpleFoam</code>, FVM).</strong> v2512 (local Docker), steady SIMPLE, laminar; Ra set by fixing <code>ν = 10⁻³</code>, <code>α = ν/Pr</code>, <code>β ΔT = 1</code>, varying <code>g</code>. Nu from <code>snGrad(T)</code> on the hot patch. Meshes 128² (Ra = 10³), 192² (Ra = 10⁵).</p><p><strong>Reference.</strong> de Vahl Davis, G. (1983), <em>Natural convection of air in a square cavity: a bench mark numerical solution</em>, Int. J. Numer. Methods Fluids 3, 249–264 — Pr = 0.71, hot-wall Nu₀ = 1.117 / 2.238 / 4.509 at Ra = 10³ / 10⁴ / 10⁵ (Table V; his cavity average Nu̅ is 1.118 / 2.243 / 4.519). Kraken computes a hot-wall mean, so this page compares with Nu₀.</p><h2 id="3D-—-cubic-cavity" tabindex="-1">3D — cubic cavity <a class="header-anchor" href="#3D-—-cubic-cavity" aria-label="Permalink to &quot;3D — cubic cavity {#3D-—-cubic-cavity}&quot;">​</a></h2><p>The same double-distribution thermal LBM extends to a <strong>cubic</strong> cavity (D3Q19 flow + D3Q19 temperature, driver <code>run_natural_convection_3d</code>), referenced to Tric et al. (2000) and cross-checked against Fusegi et al. (1991). A single-mesh exploratory run at 96³ (Metal F32) gives Nu errors of <strong>+1.45 % / +3.36 % / +6.29 %</strong> at Ra = 10³ / 10⁴ / 10⁵ vs Tric — the boundary layer thins as Ra^(1/4), so the residual grows with Ra as expected. These three points are tabulated in <code>benchmarks/results/repro/thermal/kraken_natconv_3d_results.csv</code>.</p><blockquote><p><strong>Status: preliminary, not yet a quantitative benchmark.</strong> Only the 96³ point above is bundled. A full mesh-convergence ladder (N = 48 / 64 / 96 / 128) and a Float32-vs-Float64 cross-check are not yet reproducible from this repo; reaching the &lt; 2 % gate at Ra = 10⁵ is expected to require N ≥ 128 (an HPC-class run). Consistent with the <a href="./validation-matrix">validation matrix</a>, the quantitative 3D thermal benchmark is a <strong>future item</strong>; the 3D driver is wired and smoke-validated today.</p></blockquote><p>References: Tric, E., Labrosse, G. &amp; Betrouni, M. (2000), Int. J. Heat Mass Transfer 43, 4043–4056; Fusegi, T., Hyun, J.M., Kuwahara, K. &amp; Farouk, B. (1991), Int. J. Heat Mass Transfer 34, 1543–1557.</p><h2 id="Caveats" tabindex="-1">Caveats <a class="header-anchor" href="#Caveats" aria-label="Permalink to &quot;Caveats {#Caveats}&quot;">​</a></h2><ul><li><p><strong>OpenFOAM Ra = 10⁴ is not converged</strong> in the iteration budget (Nu ≈ 1.55 at 6000 iterations, still drifting; true steady state needs ~15–20 k). It is flagged <code>_UNCONVERGED</code> in the CSV and omitted from the plot — a slow-SIMPLE artifact of the reference, not a Kraken issue; Kraken&#39;s Ra = 10⁴ stands on its independent dVD validation (+0.93 %).</p></li><li><p><strong>Low-Ra precision floor.</strong> Ra = 10³ requires Float64 (the <code>β g ∝ 1/N³</code> body force underflows F32 for <code>N ≥ 320</code>). Use CPU F64 at low Ra; reserve Metal F32 for Ra ≥ 10⁴.</p></li><li><p><strong>Rayleigh–Bénard is qualitative only.</strong> The bottom-heated, periodic-side demo (<code>examples/rayleigh_benard.krk</code>) develops convection rolls above Ra_c ≈ 1708 but asserts no quantitative roll-cell reference.</p></li></ul><h2 id="Reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#Reproduce" aria-label="Permalink to &quot;Reproduce {#Reproduce}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Kraken</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_simulation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;examples/natural_convection.krk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># differentially-heated cavity</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_simulation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;examples/rayleigh_benard.krk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># qualitative Rayleigh–Bénard</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_simulation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;examples/natural_convection_3d.krk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cubic 3D cavity</span></span></code></pre></div><p>The presets set <code>ν</code>, <code>Pr</code>, <code>Ra</code>, the thermal module and the cavity walls; set the backend and resolution per the precision recipe to reproduce a specific table entry (CPU F64 at N=192 for Ra=10³; Metal F32 at N=320/384 for Ra=10⁴/10⁵). Plots are regenerated with <code>bench/scratch/plot_thermal_natconv.jl</code> (CairoMakie, <code>--project=docs</code>).</p>`,30)])])}const m=t(n,[["render",l]]);export{y as __pageData,m as default};
